        uint256 amountOut
    ) internal {
        address[] memory path = new address[](2);
        path[0] = address(BUSDT);
        path[1] = address(DD);
        Router.swapTokensForExactTokens(
            amountOut, BUSDT.balanceOf(address(this)), path, address(this), block.timestamp + 100
        );
    }
}

