        address[] memory tokens = new address[](1);
        tokens[0] = address(cUsdc);
        uint128 currentEpoch = staking.getCurrentEpoch();
        for (uint128 i = 0; i < currentEpoch; i++) {
            staking.manualEpochInit(tokens, i);
        }
