        if (pool == address(POOL_USDT_USDCE_500)) return FLASH_2_AMOUNT;
        if (pool == address(POOL_DAI_USDCE_500)) return FLASH_3_AMOUNT;
        if (pool == address(POOL_DAI_USDCE_100)) return FLASH_4_AMOUNT;
        revert("unknown amount");
    }
