// MsgTransmitter: 0x81D40F21F12A8F0E3252Bccb954D722d4c464B64 (Circle MessageTransmitterV2)
// Aave V3 Pool : 0xA238Dd80C259a72e81d7e4664a9801593F98d1c5
// USDC (Base)  : 0x833589fCD6eDb6E08f4c7C32D4f71b54bdA02913
